def _runtime_context(record: Mapping[str, object], event: Mapping[str, object]) -> dict[str, object]:
    """Observe the bound child's exact turn, never infer effort from a request."""
    child = record["child"]
    reference = child.get("transcript_ref")
    turn = event.get("turn_id")
    result = {"state": "UNVERIFIED", "turn_id": turn, "transcript_ref": reference}
    if not reference or not turn:
        return result
    path = Path(reference)
    supplied = event.get("agent_transcript_path")
    if supplied and Path(supplied).resolve() != path.resolve():
        return {**result, "state": "MISMATCH", "reason": "CHILD_TRANSCRIPT_MISMATCH"}
    try:
        raw = path.read_bytes()
        entries = [json.loads(line) for line in raw.splitlines() if line.strip()]
    except (OSError, ValueError):
        return result
    sessions = [e.get("payload", {}).get("id") for e in entries if e.get("type") == "session_meta"]
    contexts = [e["payload"] for e in entries if e.get("type") == "turn_context"
                and e.get("payload", {}).get("turn_id") == turn]
    if not sessions or not contexts:
        return result
    if any(session != child["child_id"] for session in sessions):
        return {**result, "state": "MISMATCH", "reason": "CHILD_TRANSCRIPT_ID_MISMATCH"}
    selected = contexts[-1]
    observed = {k: selected.get(k) for k in ("model", "effort", "cwd", "sandbox_policy")}
    result.update(observed=observed, transcript_sha256=sha256(raw).hexdigest())
    if any(not observed.get(k) for k in ("model", "effort", "cwd")):
        return result
    expected = record["profile"]
    if (observed["model"] != expected["model"] or observed["effort"] != expected["effort"]
            or str(Path(observed["cwd"]).resolve()) != record["identity"]["worktree_root"]):
        return {**result, "state": "MISMATCH", "reason": "CHILD_RUNTIME_PROFILE_MISMATCH"}
    sandbox = _sandbox(observed['sandbox_policy'])
    expected_sandbox = _sandbox(expected.get('sandbox_policy', expected.get('sandbox_mode')))
    if sandbox is None or expected_sandbox is None:
        return {**result, 'reason': 'CHILD_SANDBOX_UNVERIFIED'}
    if sandbox != expected_sandbox:
        return {**result, 'state': 'MISMATCH', 'reason': 'CHILD_SANDBOX_MISMATCH'}
    return {**result, "state": "MATCH"}
    def _validate_event_identity(self, record: Mapping[str, object], event: Mapping[str, object], *, require_cwd: bool) -> None:
        if not isinstance(event, Mapping): raise _fail("CHILD_EVENT_INVALID", "Child event must be a mapping.")
        identity = record["identity"]
        if not isinstance(identity, Mapping): raise _fail("LIFECYCLE_STATE_INVALID", "Stored identity is invalid.")
        cwd = event.get("cwd")
        if require_cwd and not isinstance(cwd, str): raise _fail("CHILD_CWD_MISSING", "Child event must report actual cwd.")
        if cwd is not None and str(_absolute(cwd, "event.cwd")) != identity["worktree_root"]:
