        if current_contract != record.get("harness_contract"):
            raise _fail("HARNESS_CONTRACT_CHANGED", "Frozen harness validator changed after child exit.")

    def _revalidate_frozen_validator(self, record: Mapping[str, object]) -> None:
        """Reject a cached success when its registered validator changed."""
        self._revalidate_harness_contract(record)
        for filename, expected in record.get("validator_files", {}).items():
            path = Path(filename)
            if not path.is_file() or sha256(path.read_bytes()).hexdigest() != expected:
