DEFAULT_PATH = Path.home() / '.config/cuh-g/continuous-operation.json'


def load_policy(path: Path | None = None) -> dict:
    path = path or Path(os.environ.get('CUHG_CONTINUOUS_POLICY', str(DEFAULT_PATH)))
    if not path.exists():
        return {}
    value = json.loads(path.read_text())
    if not isinstance(value, dict) or value.get('schema') != 'cuhg-continuous-operation/v1':
