    return value


def validate_budget(value: dict) -> dict:
    if not isinstance(value, dict) or set(value) != {'mode', 'soft_target', 'explicit_hard_limit'}:
        raise ValueError('ADAPTIVE_BUDGET_INVALID')
    if value['mode'] != 'adaptive' or type(value['soft_target']) is not int or value['soft_target'] <= 0:
        raise ValueError('ADAPTIVE_BUDGET_INVALID')
    hard = value['explicit_hard_limit']
    if hard is not None and (type(hard) is not int or hard <= 0):
        raise ValueError('ADAPTIVE_BUDGET_INVALID')
    return dict(value)


def assess_budget(policy: dict, observed_tokens: int | None) -> dict:
    policy = validate_budget(policy)
    if observed_tokens is not None and (type(observed_tokens) is not int or observed_tokens < 0):
        raise ValueError('BUDGET_OBSERVATION_INVALID')
    hard = policy['explicit_hard_limit']
    if hard is not None and (observed_tokens is None or observed_tokens >= hard):
        return {'action': 'CHECKPOINT', 'reason': 'EXPLICIT_HARD_LIMIT_UNAVAILABLE_OR_EXHAUSTED'}
    if observed_tokens is None:
        return {'action': 'CONTINUE', 'reason': 'USAGE_UNKNOWN_NO_HARD_LIMIT'}
    if observed_tokens >= policy['soft_target']:
        return {'action': 'REPLAN_AND_CONTINUE', 'reason': 'SOFT_TARGET_EXCEEDED'}
    return {'action': 'CONTINUE', 'reason': 'WITHIN_SOFT_TARGET'}

